(function(global){"use strict";const DATA={"area":{"id":"science","shortTitle":"Science","eyebrow":"Texas science certification preparation","heroTitle":"Investigate the evidence. Connect the systems. Explain the science.","heroText":"Diagnostics and targeted practice for EC–6 Science 904, Core Subjects 4–8 Science 809, and standalone Science 4–8 (116).","about":"The science site includes content, scientific inquiry, safety, data interpretation, and the instruction-and-assessment applications explicitly included in the official science frameworks.","links":[{"label":"Core Subjects EC–6 (391) framework — Science 904","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_391.htm"},{"label":"Core Subjects 4–8 (211) framework — Science 809","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_211_2021.htm"},{"label":"Science 4–8 (116) framework","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_116.htm"}]},"categories":{"sci-inquiry":{"label":"Scientific Inquiry, Safety, Tools, and Data","description":"Experimental design, variables, measurement, graphing, laboratory safety, models, and the nature of science.","group":"Inquiry and Processes","questions":[{"prompt":"Which statement is a testable scientific hypothesis?","correct":"Bean plants receiving eight hours of light will grow taller in 14 days than identical plants receiving four hours of light.","distractors":["Plants need light to be healthy.","Sunlight is better than darkness.","Tall plants are more attractive than short plants."],"explanation":"A testable hypothesis identifies measurable variables and a comparison that can be investigated."},{"prompt":"In an investigation of how water temperature affects dissolving time, which variable should be placed on the horizontal axis of a graph?","correct":"Water temperature","distractors":["Dissolving time","Mass of the solute after dissolving","The title of the investigation"],"explanation":"The independent variable—water temperature—is conventionally placed on the horizontal axis."},{"prompt":"A student changes the amount of fertilizer and measures plant height. What is the dependent variable?","correct":"Plant height","distractors":["Amount of fertilizer","Type of pot","Number of plants"],"explanation":"The dependent variable is the measured response: plant height."},{"prompt":"Why are repeated trials useful in an experiment?","correct":"They reduce the influence of random variation and make results more reliable.","distractors":["They guarantee the hypothesis is correct.","They remove the need for a control group.","They allow several variables to change at once."],"explanation":"Repeated trials reveal variability and improve confidence that a pattern is not due to chance."},{"prompt":"Which procedure best improves the validity of a test comparing two brands of paper towel?","correct":"Use equal-sized sheets and the same volume of water for each brand.","distractors":["Use a different volume of water for each brand.","Let one brand soak longer than the other.","Test one sheet of each brand only once."],"explanation":"A fair comparison changes only the brand while controlling sheet size, water volume, and procedure."},{"prompt":"A balance gives measurements of 24.8 g, 24.8 g, and 24.9 g for an object whose accepted mass is 27.0 g. The measurements are best described as:","correct":"precise but not accurate.","distractors":["accurate but not precise.","both accurate and precise.","neither measurable nor repeatable."],"explanation":"The values are close to one another (precise) but not close to the accepted value (not accurate)."},{"prompt":"Which laboratory action is safest when heating a liquid in a test tube?","correct":"Point the open end away from all people.","distractors":["Seal the test tube with a stopper.","Look directly into the test tube while heating.","Hold the tube with bare fingers near the flame."],"explanation":"A heated test tube should remain open and point away from everyone because hot liquid or vapor can erupt."},{"prompt":"Which tool is most appropriate for measuring 36.5 mL of water?","correct":"A graduated cylinder","distractors":["A meterstick","A spring scale","A thermometer"],"explanation":"A graduated cylinder measures liquid volume; the other tools measure length, force, and temperature."},{"prompt":"A student needs to determine the volume of an irregular rock. Which method is best?","correct":"Measure the volume of water displaced when the rock is submerged.","distractors":["Multiply the rock’s longest length by its width.","Measure the rock’s mass twice.","Count the number of visible faces."],"explanation":"Water displacement measures the volume of an irregular solid."},{"prompt":"Which unit is an SI unit of force?","correct":"newton","distractors":["joule","watt","meter per second"],"explanation":"Force is measured in newtons; joules measure energy and watts measure power."},{"prompt":"A model of the solar system shows planet positions accurately but not their relative sizes. What does this illustrate?","correct":"Models can represent some features well while simplifying others.","distractors":["A model must reproduce every feature exactly.","Models are useful only when life-sized.","The solar system has no measurable scale."],"explanation":"Scientific models have purposes and limitations; a model may preserve position while distorting scale."},{"prompt":"Which observation is quantitative?","correct":"The liquid temperature increased from 20°C to 31°C.","distractors":["The liquid became cloudy.","The odor was sharp.","The surface felt rough."],"explanation":"Quantitative observations contain measurements or numbers."},{"prompt":"What is the primary purpose of a control group?","correct":"To provide a baseline for comparison with the treatment group.","distractors":["To receive every experimental treatment.","To ensure every subject gives the same result.","To replace repeated trials."],"explanation":"A control group shows what happens without the tested treatment."},{"prompt":"Which conclusion is justified when data do not support a hypothesis?","correct":"Revise or reject the hypothesis and use the evidence to plan further investigation.","distractors":["Change the recorded data to match the hypothesis.","Conclude that experiments cannot test the question.","Ignore results from all repeated trials."],"explanation":"Scientific conclusions follow evidence; unsupported hypotheses are revised rather than protected."},{"prompt":"Peer review contributes to science primarily by:","correct":"allowing other experts to evaluate methods, evidence, and reasoning.","distractors":["deciding scientific questions by majority vote.","preventing scientists from changing explanations.","guaranteeing that published claims can never be revised."],"explanation":"Peer review provides critical evaluation, although findings can still be revised with new evidence."},{"prompt":"A student records 0.425 m. How many centimeters is this?","correct":"42.5 cm","distractors":["4.25 cm","425 cm","0.0425 cm"],"explanation":"Because 1 meter equals 100 centimeters, 0.425 × 100 = 42.5 cm."},{"prompt":"Which investigation is comparative rather than controlled experimental?","correct":"Recording bird species found in a wooded park and a grassland park without manipulating either habitat.","distractors":["Changing light levels for identical seedlings.","Giving different salt concentrations to equal samples.","Testing friction while changing only surface type in a laboratory."],"explanation":"A comparative study examines naturally occurring differences without assigning treatments."},{"prompt":"Which graph is generally best for showing how air temperature changes during one day?","correct":"A line graph","distractors":["A circle graph","A pictograph with no time order","A single-column table"],"explanation":"A line graph displays continuous change across ordered time values."},{"prompt":"A student spills a chemical during a laboratory activity. What should the student do first?","correct":"Alert the teacher and follow the established spill procedure.","distractors":["Taste the chemical to identify it.","Wipe it up secretly with bare hands.","Mix it with another chemical to neutralize it."],"explanation":"Students should immediately notify the teacher and follow the safety plan rather than improvising."},{"prompt":"Which statement best distinguishes an observation from an inference?","correct":"An observation is gathered with senses or instruments; an inference interprets what the observation may mean.","distractors":["An observation is always an opinion; an inference is always a measurement.","An inference must be visible; an observation is hidden.","There is no difference between them."],"explanation":"Observations are direct evidence; inferences are reasoned explanations based on evidence."}]},"sci-physical":{"label":"Force, Motion, Energy, Waves, and Electricity","description":"Mechanics, simple machines, energy transformations, heat transfer, waves, light, sound, circuits, and magnetism.","group":"Physical Science","questions":[{"prompt":"A 3 kg object accelerates at 4 m/s². What net force acts on it?","correct":"12 N","distractors":["0.75 N","7 N","24 N"],"explanation":"Newton’s second law gives F = ma = 3 × 4 = 12 N."},{"prompt":"A car travels 150 km in 3 hours at a constant rate. What is its average speed?","correct":"50 km/h","distractors":["450 km/h","147 km/h","0.02 km/h"],"explanation":"Average speed equals distance divided by time: 150 ÷ 3 = 50 km/h."},{"prompt":"Which situation has balanced forces?","correct":"A book rests motionless on a level table.","distractors":["A dropped ball speeds up.","A bicycle turns a corner.","A cart accelerates after being pushed."],"explanation":"The downward gravitational force on the book is balanced by the table’s upward normal force."},{"prompt":"When a swimmer pushes water backward, the water pushes the swimmer forward. This is an example of:","correct":"Newton’s third law.","distractors":["the law of conservation of mass only.","electromagnetic induction.","thermal equilibrium."],"explanation":"Forces occur in equal and opposite interaction pairs."},{"prompt":"Which change increases an object’s gravitational potential energy near Earth’s surface?","correct":"Raising the object to a greater height.","distractors":["Cooling the object.","Reducing its speed while keeping its height fixed.","Moving it horizontally at the same height."],"explanation":"Near Earth, gravitational potential energy increases with mass, gravity, and height."},{"prompt":"A moving skateboard slows after the rider stops pushing primarily because:","correct":"friction and air resistance exert forces opposite the motion.","distractors":["inertia requires moving objects to stop.","gravity disappears.","the skateboard loses all mass."],"explanation":"Resistive forces oppose motion and reduce kinetic energy."},{"prompt":"Which simple machine is a ramp?","correct":"Inclined plane","distractors":["Pulley","Wheel and axle","Lever"],"explanation":"A ramp is an inclined plane that trades a longer distance for a smaller input force."},{"prompt":"A machine cannot produce more work than the work put into it because of:","correct":"conservation of energy.","distractors":["the law of definite proportions.","continental drift.","natural selection."],"explanation":"Machines transform energy; they do not create energy, and real machines lose some usable energy to friction."},{"prompt":"Sound cannot travel through:","correct":"a perfect vacuum.","distractors":["steel","water","air"],"explanation":"Sound is a mechanical wave and requires matter through which particles can vibrate."},{"prompt":"Which property of a sound wave is most directly related to pitch?","correct":"Frequency","distractors":["Amplitude","Speed in a fixed medium","Total energy only"],"explanation":"Higher frequency corresponds to higher pitch."},{"prompt":"Which property of a sound wave is most closely related to loudness?","correct":"Amplitude","distractors":["Wavelength only","Direction","Color"],"explanation":"Greater amplitude generally carries more energy and is perceived as louder."},{"prompt":"When light passes from air into glass and changes direction, the effect is called:","correct":"refraction.","distractors":["reflection.","conduction.","resonance."],"explanation":"Refraction is the bending of a wave as its speed changes between media."},{"prompt":"A mirror forms an image because light undergoes:","correct":"reflection.","distractors":["radioactive decay.","convection.","chemical bonding."],"explanation":"Reflection occurs when light bounces from a surface."},{"prompt":"Which material is generally the best electrical conductor?","correct":"Copper","distractors":["Rubber","Glass","Dry wood"],"explanation":"Metals such as copper have mobile electrons that carry electric current readily."},{"prompt":"In a simple series circuit, what happens if one bulb is removed?","correct":"The circuit opens and all bulbs go out.","distractors":["The remaining bulbs receive current through a new branch.","The battery becomes an insulator.","Current continues through the missing bulb."],"explanation":"A series circuit has one path; removing a component breaks that path."},{"prompt":"In a parallel circuit, each branch:","correct":"provides a separate path for current.","distractors":["must contain the same number of components.","has no voltage across it.","is connected end-to-end in one path only."],"explanation":"Parallel branches allow current to divide among multiple paths."},{"prompt":"Which energy transformation occurs in a battery-powered flashlight?","correct":"Chemical energy → electrical energy → light and thermal energy","distractors":["Light energy → nuclear energy → chemical energy","Thermal energy → gravitational energy only","Electrical energy → chemical energy only"],"explanation":"The battery’s chemical energy drives current, and the bulb converts electrical energy to light and heat."},{"prompt":"Thermal energy transfers through direct contact mainly by:","correct":"conduction.","distractors":["convection only.","radiation only.","evaporation only."],"explanation":"Conduction transfers energy through particle collisions in contacting materials."},{"prompt":"Warm air rising above a heater is an example of:","correct":"convection.","distractors":["conduction through a solid.","reflection.","magnetization."],"explanation":"Density differences produce circulating fluid motion called convection."},{"prompt":"Energy from the Sun reaches Earth mainly by:","correct":"electromagnetic radiation.","distractors":["conduction through space.","convection through a vacuum.","sound waves."],"explanation":"Radiation can travel through the vacuum of space."},{"prompt":"Which statement about magnets is correct?","correct":"Like poles repel and unlike poles attract.","distractors":["All metals are strongly magnetic.","A magnet has only one pole.","Magnetic force requires direct contact."],"explanation":"Magnetic poles interact at a distance; north-north and south-south repel, while unlike poles attract."},{"prompt":"An object moves in a circle at constant speed. Why is it accelerating?","correct":"Its velocity changes because its direction changes.","distractors":["Its mass continually increases.","No force acts on it.","Speed and velocity are identical scalars."],"explanation":"Acceleration is any change in velocity, including a change in direction."},{"prompt":"Which object has the greatest kinetic energy?","correct":"A 4 kg object moving at 6 m/s","distractors":["A 4 kg object at rest","A 2 kg object moving at 3 m/s","A 1 kg object moving at 4 m/s"],"explanation":"Kinetic energy is ½mv²; the 4 kg object at 6 m/s has the largest value."},{"prompt":"A 60 W light bulb operating for 10 seconds converts how much energy?","correct":"600 J","distractors":["6 J","70 J","6000 J"],"explanation":"Power equals energy divided by time, so energy = 60 J/s × 10 s = 600 J."},{"prompt":"Which statement describes inertia?","correct":"An object resists changes in its state of motion.","distractors":["A force is required to maintain every constant velocity.","Only moving objects have mass.","Acceleration occurs without net force."],"explanation":"Inertia is the tendency of matter to resist changes in velocity."}]},"sci-chem":{"label":"Matter, Atoms, Reactions, and Solutions","description":"Properties and states of matter, atomic structure, periodic patterns, mixtures, reactions, acids, bases, and bonding.","group":"Physical Science","questions":[{"prompt":"Which property is characteristic rather than dependent on sample size?","correct":"Density","distractors":["Mass","Volume","Total thermal energy"],"explanation":"Density is an intensive property; mass and volume depend on the amount of substance."},{"prompt":"A sample has a mass of 54 g and a volume of 20 cm³. What is its density?","correct":"2.7 g/cm³","distractors":["0.37 g/cm³","34 g/cm³","74 g/cm³"],"explanation":"Density = mass ÷ volume = 54 ÷ 20 = 2.7 g/cm³."},{"prompt":"Which change is physical?","correct":"Ice melting","distractors":["Iron rusting","Wood burning","Milk souring"],"explanation":"Melting changes state without creating a new substance."},{"prompt":"Which change is chemical?","correct":"A metal forming an oxide coating","distractors":["Water freezing","Sugar dissolving in water","A wire being bent"],"explanation":"Oxidation forms a new substance and is therefore a chemical change."},{"prompt":"Which observation most strongly indicates a chemical reaction?","correct":"A new solid precipitate forms when two clear solutions are mixed.","distractors":["A solid is cut into smaller pieces.","A liquid is poured into another container.","A substance changes shape under pressure."],"explanation":"Formation of a new substance, such as a precipitate, is evidence of chemical change."},{"prompt":"The atomic number of an element equals the number of:","correct":"protons in its nucleus.","distractors":["neutrons only.","electron shells.","molecules in a sample."],"explanation":"Element identity is determined by proton number."},{"prompt":"A neutral atom with 8 protons has how many electrons?","correct":"8","distractors":["16","4","0"],"explanation":"A neutral atom has equal numbers of positive protons and negative electrons."},{"prompt":"Isotopes of the same element differ in their numbers of:","correct":"neutrons.","distractors":["protons.","atomic numbers.","chemical symbols."],"explanation":"Isotopes share the same proton number but have different neutron numbers."},{"prompt":"Elements in the same vertical group of the periodic table often have similar chemical behavior because they have similar:","correct":"valence-electron patterns.","distractors":["numbers of occupied nuclei.","sample masses.","melting histories."],"explanation":"Valence electrons largely determine bonding and reactivity."},{"prompt":"Which subatomic particle has a negative charge?","correct":"Electron","distractors":["Proton","Neutron","Nucleus"],"explanation":"Electrons are negatively charged; protons are positive and neutrons are neutral."},{"prompt":"In a chemical equation, coefficients are adjusted to satisfy conservation of:","correct":"atoms and mass.","distractors":["temperature.","volume in every reaction.","color."],"explanation":"Balanced equations contain the same number of each type of atom on both sides."},{"prompt":"Which mixture can be separated most directly by filtration?","correct":"Sand and water","distractors":["Salt dissolved completely in water","Two gases mixed together","Sugar solution"],"explanation":"Filtration traps an insoluble solid while the liquid passes through."},{"prompt":"Which method is best for recovering dissolved salt from saltwater?","correct":"Evaporate the water.","distractors":["Use a magnet.","Filter through paper only.","Decant without evaporation."],"explanation":"Evaporation removes the solvent and leaves the dissolved solid."},{"prompt":"A solution with pH 3 is:","correct":"acidic.","distractors":["neutral.","basic.","necessarily pure water."],"explanation":"Values below 7 are acidic; 7 is neutral and values above 7 are basic."},{"prompt":"When an acid and a base react in suitable amounts, the products commonly include:","correct":"a salt and water.","distractors":["only oxygen gas.","a metal and a nonmetal.","two acids."],"explanation":"Neutralization commonly produces water and an ionic salt."},{"prompt":"Which state of matter has definite volume but takes the shape of its container?","correct":"Liquid","distractors":["Solid","Gas","Plasma only at all temperatures"],"explanation":"Liquids retain volume but flow to match container shape."},{"prompt":"During boiling at constant pressure, added energy primarily:","correct":"separates particles during the phase change rather than raising temperature.","distractors":["destroys all molecules.","decreases particle motion to zero.","changes the substance into a new element."],"explanation":"Latent heat goes into overcoming intermolecular attractions while temperature remains nearly constant."},{"prompt":"Which statement is part of the particle model of matter?","correct":"Particles are in constant motion, and their motion generally increases with temperature.","distractors":["Particles in liquids have no motion.","Matter contains no empty space.","Heating always increases particle size."],"explanation":"Kinetic particle theory links temperature to average particle motion."},{"prompt":"Which bond involves sharing electron pairs between atoms?","correct":"Covalent bond","distractors":["Ionic bond only","Magnetic bond","Gravitational bond"],"explanation":"Covalent bonds form through shared electron pairs."},{"prompt":"An ionic compound commonly forms when:","correct":"electrons are transferred between a metal and a nonmetal.","distractors":["two noble gases share many electrons.","neutrons move between molecules.","atoms lose their nuclei."],"explanation":"Electron transfer creates oppositely charged ions that attract."}]},"sci-life":{"label":"Cells, Heredity, Evolution, and Organ Systems","description":"Cell structure and processes, genetics, reproduction, evolution, microorganisms, plants, and human systems.","group":"Life Science","questions":[{"prompt":"Which structure controls movement of substances into and out of a cell?","correct":"Cell membrane","distractors":["Cell wall only","Nucleus only","Chromosome"],"explanation":"The selectively permeable cell membrane regulates exchange with the environment."},{"prompt":"Which organelle carries out most cellular respiration in eukaryotic cells?","correct":"Mitochondrion","distractors":["Ribosome","Golgi apparatus","Cell wall"],"explanation":"Mitochondria release usable energy from food molecules through cellular respiration."},{"prompt":"Photosynthesis occurs mainly in the:","correct":"chloroplasts.","distractors":["lysosomes.","nuclei.","cell membranes of animal cells."],"explanation":"Chloroplasts contain chlorophyll and the structures used in photosynthesis."},{"prompt":"Which equation best summarizes photosynthesis?","correct":"Carbon dioxide + water + light energy → glucose + oxygen","distractors":["Glucose + oxygen → carbon dioxide + water + usable energy","Nitrogen + oxygen → protein","Water → carbon dioxide + minerals"],"explanation":"Photosynthesis stores light energy by producing glucose from carbon dioxide and water."},{"prompt":"The primary function of ribosomes is to:","correct":"assemble proteins.","distractors":["store hereditary information.","digest all waste.","produce cell walls from sunlight."],"explanation":"Ribosomes translate genetic instructions into proteins."},{"prompt":"A group of similar cells working together forms a:","correct":"tissue.","distractors":["organism only.","molecule.","population."],"explanation":"Cells form tissues; tissues form organs; organs form organ systems."},{"prompt":"Which body system transports oxygen, nutrients, hormones, and wastes?","correct":"Circulatory system","distractors":["Skeletal system","Integumentary system only","Reproductive system"],"explanation":"Blood and vessels distribute materials throughout the body."},{"prompt":"Gas exchange between air and blood occurs primarily in the:","correct":"alveoli of the lungs.","distractors":["stomach.","kidneys.","bones."],"explanation":"Thin-walled alveoli provide a large surface for diffusion of oxygen and carbon dioxide."},{"prompt":"Which organ filters blood and helps regulate water and ion balance?","correct":"Kidney","distractors":["Lung","Pancreas","Femur"],"explanation":"Kidneys remove wastes and help maintain fluid and electrolyte balance."},{"prompt":"Homeostasis refers to an organism’s ability to:","correct":"maintain relatively stable internal conditions.","distractors":["avoid all environmental change.","produce only identical offspring.","stop using energy."],"explanation":"Feedback systems maintain variables such as temperature, pH, and glucose within functional ranges."},{"prompt":"Mitosis normally produces:","correct":"two genetically similar daughter cells.","distractors":["four genetically varied gametes.","one cell with no chromosomes.","two cells with twice the parent chromosome number."],"explanation":"Mitosis copies and distributes chromosomes for growth and repair."},{"prompt":"Meiosis is important because it:","correct":"produces haploid gametes and contributes to genetic variation.","distractors":["produces identical body cells only.","doubles chromosome number every generation.","occurs only in bacteria."],"explanation":"Meiosis reduces chromosome number and creates variation through independent assortment and crossing over."},{"prompt":"A segment of DNA that contains instructions for a functional product is a:","correct":"gene.","distractors":["tissue.","lipid.","mineral."],"explanation":"A gene is a DNA sequence that contributes to a functional RNA or protein product."},{"prompt":"If a dominant allele is represented by A, which genotype is heterozygous?","correct":"Aa","distractors":["AA","aa","A only"],"explanation":"Heterozygous means possessing two different alleles."},{"prompt":"Two heterozygous parents for a simple dominant trait are crossed: Aa × Aa. What fraction of offspring is expected to have genotype aa?","correct":"1/4","distractors":["1/2","3/4","1"],"explanation":"The Punnett outcomes are AA, Aa, Aa, and aa; one of four is aa."},{"prompt":"Natural selection occurs when:","correct":"heritable traits affecting survival or reproduction become more common over generations.","distractors":["organisms change traits because they need them during life.","every individual has identical reproductive success.","acquired muscle strength is always inherited."],"explanation":"Natural selection changes populations when heritable variation influences reproductive success."},{"prompt":"Which evidence most directly supports common ancestry?","correct":"Different species share homologous DNA sequences and anatomical structures.","distractors":["All organisms live in identical habitats.","Every species has the same number of chromosomes.","Fossils occur only in recent rocks."],"explanation":"Shared inherited molecular and structural features support descent from common ancestors."},{"prompt":"Bacteria are classified as prokaryotes because they:","correct":"lack a membrane-bound nucleus.","distractors":["have no DNA.","are always harmful.","cannot reproduce."],"explanation":"Prokaryotic DNA is not enclosed in a membrane-bound nucleus."},{"prompt":"A virus can reproduce only by:","correct":"using the machinery of a host cell.","distractors":["performing photosynthesis independently.","dividing by mitosis outside a host.","feeding on minerals."],"explanation":"Viruses lack the cellular machinery for independent reproduction."},{"prompt":"Which plant tissue transports water and dissolved minerals upward from roots?","correct":"Xylem","distractors":["Phloem","Epidermis only","Pollen"],"explanation":"Xylem conducts water and minerals; phloem transports sugars and other organic products."},{"prompt":"Which plant response causes a shoot to grow toward light?","correct":"Phototropism","distractors":["Hibernation","Fermentation","Osmosis only"],"explanation":"Phototropism is directional growth in response to light."},{"prompt":"Diffusion is the net movement of particles:","correct":"from higher concentration toward lower concentration.","distractors":["only from low temperature to high temperature.","against a concentration gradient without energy in every case.","only through solid walls."],"explanation":"Random motion produces net movement down a concentration gradient."},{"prompt":"Osmosis is specifically the diffusion of:","correct":"water across a selectively permeable membrane.","distractors":["proteins through bone.","electrons through a wire.","oxygen through a vacuum."],"explanation":"Osmosis describes water movement across a selectively permeable membrane."},{"prompt":"Which macromolecule is the main immediate source of energy for many cells?","correct":"Carbohydrates","distractors":["Nucleic acids","Minerals","Water"],"explanation":"Carbohydrates such as glucose are commonly broken down to release usable energy."},{"prompt":"Enzymes speed biological reactions by:","correct":"lowering activation energy.","distractors":["being permanently consumed in every reaction.","raising the required activation energy.","changing the final equilibrium products into elements."],"explanation":"Enzymes are catalysts that lower activation energy without being used up."}]},"sci-ecology":{"label":"Ecology and Environmental Systems","description":"Populations, communities, food webs, cycles of matter, succession, biodiversity, and ecosystem interactions.","group":"Life Science","questions":[{"prompt":"A population consists of:","correct":"members of one species living in the same area.","distractors":["all abiotic factors in a region.","every ecosystem on Earth.","several unrelated organs."],"explanation":"A population is a group of individuals of the same species in a defined area."},{"prompt":"A community includes:","correct":"all interacting populations in an area.","distractors":["only the nonliving environment.","one individual organism.","one species and no others."],"explanation":"A community contains populations of different species."},{"prompt":"An ecosystem includes a community plus:","correct":"the nonliving environment with which organisms interact.","distractors":["only predators.","only plants.","organisms from another planet."],"explanation":"Ecosystems include biotic and abiotic components and their interactions."},{"prompt":"Which organism is a producer?","correct":"A grass plant","distractors":["A hawk","A mushroom","A rabbit"],"explanation":"Producers capture energy, usually through photosynthesis, and form the base of food webs."},{"prompt":"What is the primary ecological role of decomposers?","correct":"Break down dead material and recycle nutrients.","distractors":["Create energy from nothing.","Remove all oxygen from ecosystems.","Convert consumers directly into sunlight."],"explanation":"Decomposers return matter to forms that can reenter nutrient cycles."},{"prompt":"In the food chain grass → rabbit → fox, the rabbit is a:","correct":"primary consumer.","distractors":["producer.","decomposer.","tertiary consumer."],"explanation":"The rabbit eats the producer and is therefore a primary consumer."},{"prompt":"Why is less energy available at higher trophic levels?","correct":"Organisms use much of the energy for life processes and release heat.","distractors":["Energy is destroyed by producers.","Matter cannot move through food webs.","Consumers contain no chemical energy."],"explanation":"Energy transfer is inefficient; much energy is used in metabolism and dissipated as heat."},{"prompt":"Carrying capacity is the:","correct":"largest population an environment can support sustainably under given conditions.","distractors":["number of species that can migrate in one day.","minimum age for reproduction.","amount of sunlight reflected by a habitat."],"explanation":"Resources and limiting factors constrain long-term population size."},{"prompt":"Which factor is density dependent?","correct":"Competition for limited food","distractors":["A volcanic eruption","A hurricane","A sudden freeze"],"explanation":"Competition intensifies as population density increases."},{"prompt":"Which interaction benefits both species?","correct":"Mutualism","distractors":["Predation","Parasitism","Competition"],"explanation":"In mutualism, both participants receive a benefit."},{"prompt":"A tick feeding on a dog is an example of:","correct":"parasitism.","distractors":["mutualism.","commensalism.","primary production."],"explanation":"The tick benefits while harming the host."},{"prompt":"Primary succession begins in an area:","correct":"with little or no soil, such as newly exposed rock.","distractors":["where an intact mature forest remains unchanged.","only after seasonal leaf fall.","with complete soil and seed banks after a small fire."],"explanation":"Primary succession starts where soil must first develop."},{"prompt":"Which process removes carbon dioxide from the atmosphere?","correct":"Photosynthesis","distractors":["Cellular respiration","Combustion","Decomposition only"],"explanation":"Photosynthetic organisms use atmospheric or dissolved carbon dioxide to build organic molecules."},{"prompt":"Nitrogen-fixing bacteria are important because they:","correct":"convert atmospheric nitrogen into forms usable in ecosystems.","distractors":["destroy all nitrogen compounds.","produce sunlight.","turn oxygen into carbon."],"explanation":"Most organisms cannot use N₂ directly; fixation makes nitrogen biologically available."},{"prompt":"Water vapor enters the atmosphere from plant leaves through:","correct":"transpiration.","distractors":["condensation.","infiltration.","freezing."],"explanation":"Transpiration is evaporation of water from plant surfaces, especially through stomata."},{"prompt":"An invasive species may reduce biodiversity when it:","correct":"outcompetes native species and lacks effective local controls.","distractors":["always increases resources for every native species.","cannot reproduce in the new area.","occupies no ecological niche."],"explanation":"Invasive species can spread rapidly and disrupt existing interactions."},{"prompt":"Which change would most likely increase biodiversity in a fragmented habitat?","correct":"Creating wildlife corridors between habitat patches.","distractors":["Building wider barriers between patches.","Removing native vegetation.","Introducing several nonnative predators."],"explanation":"Corridors improve movement and gene flow among separated populations."},{"prompt":"Biomagnification refers to:","correct":"increasing concentration of certain persistent pollutants at higher trophic levels.","distractors":["the conversion of all pollutants into nutrients.","a decrease in organism size at higher levels.","the growth of a single cell under a microscope."],"explanation":"Persistent substances accumulate in tissues and can reach high concentrations in top consumers."},{"prompt":"Which is an abiotic factor?","correct":"Soil pH","distractors":["Bacteria","Oak trees","Earthworms"],"explanation":"Abiotic factors are nonliving physical or chemical features."},{"prompt":"A keystone species has:","correct":"an ecological effect disproportionately large relative to its abundance.","distractors":["no interactions with other species.","the greatest body size in every ecosystem.","a role limited to producing oxygen."],"explanation":"Removing a keystone species can cause major community changes."}]},"sci-earth":{"label":"Earth Systems, Geology, Weather, and Climate","description":"Earth structure, plate tectonics, rocks, water, weather, climate, oceans, resources, and surface processes.","group":"Earth and Space","questions":[{"prompt":"Which layer of Earth is liquid and composed mainly of iron and nickel?","correct":"Outer core","distractors":["Inner core","Crust","Lithosphere only"],"explanation":"The outer core is liquid; motion there contributes to Earth’s magnetic field."},{"prompt":"Plate tectonics is driven largely by:","correct":"heat transfer and mantle motion within Earth.","distractors":["daily ocean tides alone.","the Moon’s phases.","weathering at the surface only."],"explanation":"Internal heat and mantle convection contribute to plate movement."},{"prompt":"New oceanic crust forms mainly at:","correct":"divergent plate boundaries.","distractors":["continental collision zones only.","transform boundaries only.","subduction trenches only."],"explanation":"Magma rises and solidifies where plates move apart at mid-ocean ridges."},{"prompt":"A deep-ocean trench commonly forms where:","correct":"one plate subducts beneath another.","distractors":["two plates move apart without sinking.","sediment evaporates.","a river reaches the sea."],"explanation":"Subduction bends the descending plate and creates a trench."},{"prompt":"Most earthquakes occur:","correct":"near tectonic plate boundaries.","distractors":["only at the equator.","only during thunderstorms.","uniformly across all continents."],"explanation":"Stress accumulates and is released where plates interact."},{"prompt":"Which process breaks rock into smaller pieces without moving it?","correct":"Weathering","distractors":["Erosion","Deposition","Subduction"],"explanation":"Weathering breaks down rock; erosion transports the material."},{"prompt":"Which process transports weathered sediment?","correct":"Erosion","distractors":["Crystallization","Metamorphism only","Photosynthesis"],"explanation":"Water, wind, ice, and gravity erode and move sediment."},{"prompt":"Sedimentary rock often forms through:","correct":"compaction and cementation of sediments.","distractors":["melting and rapid cooling only.","nuclear fusion.","evaporation of all minerals from magma."],"explanation":"Deposited sediments can be compacted and cemented into rock."},{"prompt":"Metamorphic rock forms when existing rock is changed by:","correct":"heat and pressure without complete melting.","distractors":["only freezing rain.","photosynthesis.","complete vaporization."],"explanation":"Metamorphism alters minerals and texture under heat, pressure, and fluids."},{"prompt":"Which resource is renewable on a human time scale?","correct":"Wind energy","distractors":["Coal","Petroleum","Natural gas"],"explanation":"Wind is continually replenished; fossil fuels form over geologic time."},{"prompt":"Groundwater is stored primarily in:","correct":"pores and fractures in soil and rock.","distractors":["empty underground rivers in every location.","the outer core.","clouds below the surface."],"explanation":"Aquifers hold water in connected pore spaces and fractures."},{"prompt":"The water table is the:","correct":"upper surface of the saturated groundwater zone.","distractors":["top of every mountain watershed.","boundary between crust and mantle.","level at which seawater boils."],"explanation":"Below the water table, available pore spaces are saturated with water."},{"prompt":"Clouds form when water vapor:","correct":"cools and condenses onto tiny particles.","distractors":["is heated until it becomes solid.","loses all mass.","changes into oxygen."],"explanation":"Cooling air can reach saturation, allowing vapor to condense into droplets or ice crystals."},{"prompt":"A cold front commonly occurs when:","correct":"a colder air mass advances and lifts warmer air.","distractors":["warm air permanently stops moving.","two oceans collide.","Earth’s axis changes direction."],"explanation":"Advancing dense cold air forces warmer air upward, often producing a narrow band of weather."},{"prompt":"Which instrument measures atmospheric pressure?","correct":"Barometer","distractors":["Anemometer","Rain gauge","Seismograph"],"explanation":"A barometer measures air pressure; an anemometer measures wind speed."},{"prompt":"Climate differs from weather because climate describes:","correct":"long-term patterns and averages, whereas weather describes short-term conditions.","distractors":["only daily wind speed.","conditions inside buildings.","a single storm."],"explanation":"Climate summarizes typical conditions over long periods."},{"prompt":"The greenhouse effect warms Earth because certain gases:","correct":"absorb and reemit outgoing infrared radiation.","distractors":["block all incoming visible light.","create energy from nothing.","stop atmospheric circulation."],"explanation":"Greenhouse gases slow the loss of thermal infrared energy to space."},{"prompt":"Ocean currents redistribute thermal energy and are influenced by:","correct":"winds, Earth’s rotation, and density differences.","distractors":["only lunar eclipses.","only earthquakes.","the color of ocean water."],"explanation":"Surface winds and Coriolis effects drive currents, while temperature and salinity influence deep circulation."},{"prompt":"Which evidence helps scientists reconstruct past climates?","correct":"Ice cores containing trapped gases and isotope records","distractors":["Only tomorrow’s weather forecast","Current road maps alone","The daily classroom temperature"],"explanation":"Ice cores preserve layered chemical and atmospheric evidence from the past."},{"prompt":"A watershed is:","correct":"the land area that drains to a common body of water.","distractors":["an underground rock layer that never contains water.","the boundary between two air masses.","a machine for desalination."],"explanation":"Topography directs runoff from a watershed toward a shared outlet."}]},"sci-space":{"label":"Astronomy and the Earth–Moon–Sun System","description":"Seasons, phases, eclipses, tides, solar-system objects, stars, galaxies, and cosmology.","group":"Earth and Space","questions":[{"prompt":"The main reason Earth experiences seasons is:","correct":"Earth’s axis is tilted as Earth revolves around the Sun.","distractors":["Earth is much closer to the Sun in summer everywhere.","The Sun changes its energy output each season.","Clouds block sunlight in winter worldwide."],"explanation":"Axial tilt changes sun angle and day length in each hemisphere during the orbit."},{"prompt":"Day and night are caused by Earth’s:","correct":"rotation on its axis.","distractors":["revolution around the Sun.","distance from the Moon.","changing magnetic field."],"explanation":"As Earth rotates, locations move into and out of sunlight."},{"prompt":"One complete revolution of Earth around the Sun takes about:","correct":"one year.","distractors":["one day.","one month.","one hour."],"explanation":"The orbital period defines the year."},{"prompt":"The Moon’s phases result from:","correct":"the changing portion of the Moon’s sunlit half visible from Earth.","distractors":["Earth’s shadow covering the Moon every week.","the Moon producing different amounts of light.","clouds in Earth’s atmosphere."],"explanation":"Half the Moon is illuminated by the Sun; its position changes the portion we see."},{"prompt":"A lunar eclipse occurs when:","correct":"Earth moves between the Sun and the Moon.","distractors":["the Moon moves between Earth and the Sun.","the Sun moves between Earth and the Moon.","Mars blocks the Moon."],"explanation":"Earth’s shadow falls on the Moon during a lunar eclipse."},{"prompt":"A solar eclipse occurs when:","correct":"the Moon moves between Earth and the Sun.","distractors":["Earth moves between the Sun and Moon.","the Moon enters Mars’s shadow.","the Sun stops emitting light."],"explanation":"The Moon blocks some or all of the Sun from particular locations on Earth."},{"prompt":"Ocean tides are caused mainly by:","correct":"the gravitational pull of the Moon, with a contribution from the Sun.","distractors":["Earth’s magnetic field only.","daily changes in air temperature only.","volcanic eruptions only."],"explanation":"Differential gravitational forces produce tidal bulges."},{"prompt":"The Sun produces energy primarily through:","correct":"nuclear fusion.","distractors":["chemical burning of oxygen.","nuclear fission of heavy metals.","friction with planets."],"explanation":"Hydrogen nuclei fuse into helium in the Sun’s core, releasing energy."},{"prompt":"Which object is a star?","correct":"The Sun","distractors":["The Moon","Earth","A comet nucleus"],"explanation":"The Sun is the star at the center of the solar system."},{"prompt":"A light-year is a unit of:","correct":"distance.","distractors":["time.","brightness.","mass."],"explanation":"A light-year is the distance light travels in one year."},{"prompt":"Which planet is known for its prominent ring system?","correct":"Saturn","distractors":["Mercury","Venus","Mars"],"explanation":"All giant planets have rings, but Saturn’s are especially extensive and visible."},{"prompt":"The asteroid belt lies mainly between the orbits of:","correct":"Mars and Jupiter.","distractors":["Earth and Mars.","Jupiter and Saturn.","Mercury and Venus."],"explanation":"Most main-belt asteroids orbit between Mars and Jupiter."},{"prompt":"A comet’s tail generally points:","correct":"away from the Sun.","distractors":["toward the Sun.","toward Earth at all times.","in the direction of the nearest planet."],"explanation":"Solar radiation and solar wind push dust and ions away from the Sun."},{"prompt":"Why do astronauts appear weightless while orbiting Earth?","correct":"They and their spacecraft are in continuous free fall around Earth.","distractors":["Earth exerts no gravity in orbit.","Their mass becomes zero.","Air pressure cancels gravity."],"explanation":"Orbital objects continually fall toward Earth while moving forward fast enough to miss it."},{"prompt":"A galaxy is:","correct":"a vast gravitationally bound system of stars, gas, dust, and dark matter.","distractors":["a single planet with moons.","a pattern of stars seen from Earth only.","the atmosphere of a star."],"explanation":"Galaxies contain enormous numbers of stars and other matter."},{"prompt":"The Big Bang model is supported by observations including:","correct":"expansion of the universe and the cosmic microwave background.","distractors":["a stationary universe with no background radiation.","identical ages for all rocks on Earth.","the absence of distant galaxies."],"explanation":"Galaxy redshifts and relic microwave radiation are major lines of evidence."},{"prompt":"Which statement correctly compares mass and weight?","correct":"Mass measures amount of matter; weight is the gravitational force on that mass.","distractors":["Mass changes to zero on the Moon.","Weight is measured in kilograms only.","They are always numerically identical in every location."],"explanation":"Mass is intrinsic; weight depends on local gravitational field strength."},{"prompt":"Why can astronomers learn about stars by studying spectra?","correct":"Spectral lines reveal composition, temperature, and motion.","distractors":["Stars must be touched to identify elements.","All stars produce identical spectra.","Spectra contain no information about wavelength."],"explanation":"Atoms absorb and emit characteristic wavelengths, and Doppler shifts reveal motion."}]},"sci-impact":{"label":"Science, Technology, Health, and Society","description":"Resources, energy, pollution, public health, sustainability, risk, climate responses, and evidence-based decisions.","group":"Science and Society","questions":[{"prompt":"Which action most directly conserves a nonrenewable resource?","correct":"Reducing gasoline use through carpooling and efficient transportation.","distractors":["Leaving lights on all day.","Increasing single-use plastic consumption.","Removing insulation from buildings."],"explanation":"Petroleum is nonrenewable, so reduced fuel consumption conserves it."},{"prompt":"Which energy source produces electricity without direct carbon dioxide emissions during operation?","correct":"Wind turbine","distractors":["Coal-fired power plant","Gasoline generator","Diesel engine"],"explanation":"Wind turbines do not burn carbon fuels during operation, though manufacturing still has environmental costs."},{"prompt":"A major disadvantage of fossil-fuel combustion is that it:","correct":"releases greenhouse gases and air pollutants.","distractors":["uses an infinitely renewable fuel.","removes all carbon dioxide from air.","creates no waste products."],"explanation":"Combustion releases carbon dioxide and often particulates, sulfur compounds, and nitrogen oxides."},{"prompt":"Which practice best reduces eutrophication in lakes?","correct":"Limit fertilizer runoff into waterways.","distractors":["Add more phosphate detergent to streams.","Remove shoreline vegetation.","Increase untreated sewage discharge."],"explanation":"Excess nitrogen and phosphorus stimulate algal growth and oxygen depletion."},{"prompt":"Why is vaccination a public-health tool?","correct":"It reduces the number of susceptible hosts and can slow disease transmission.","distractors":["It guarantees no vaccinated person can ever become infected.","It treats all bacterial disease with antibiotics.","It increases pathogen reproduction."],"explanation":"Vaccination prepares immune responses and can reduce transmission at the population level."},{"prompt":"Antibiotics are generally ineffective against viral infections because:","correct":"viruses do not have the bacterial structures and processes targeted by antibiotics.","distractors":["viruses are larger than all bacteria.","antibiotics work only at low temperatures.","viruses contain no genetic material."],"explanation":"Antibiotics target bacterial features such as cell walls or ribosomes, which viruses lack."},{"prompt":"Which change most directly reduces household energy demand for heating and cooling?","correct":"Improving insulation and sealing air leaks.","distractors":["Opening windows while air conditioning runs.","Replacing LED bulbs with incandescent bulbs.","Removing shade from west-facing windows."],"explanation":"Insulation and air sealing reduce unwanted heat transfer."},{"prompt":"A scientific risk-benefit analysis should consider:","correct":"evidence, uncertainty, likely consequences, costs, and ethical or social factors.","distractors":["only the most favorable possible outcome.","only whether a technology is new.","personal preference with no evidence."],"explanation":"Societal decisions require weighing evidence and trade-offs, including uncertainty."},{"prompt":"Which practice most directly protects groundwater near a well?","correct":"Properly dispose of chemicals and maintain distance from contamination sources.","distractors":["Pour solvents onto soil near the well.","Store leaking fuel containers beside the well.","Remove protective well casing."],"explanation":"Pollutants can infiltrate soil and reach aquifers; proper disposal and protection reduce risk."},{"prompt":"Sustainable harvesting means using a biological resource:","correct":"at a rate that allows populations and ecosystems to replenish.","distractors":["as rapidly as possible regardless of reproduction.","only after eliminating predators.","without monitoring population trends."],"explanation":"Sustainability keeps long-term use within renewal capacity."},{"prompt":"Which is the best example of mitigation of climate change?","correct":"Reducing greenhouse-gas emissions through efficiency and low-carbon energy.","distractors":["Building a sea wall without reducing emissions.","Moving homes away from a floodplain only.","Increasing fossil-fuel combustion."],"explanation":"Mitigation addresses causes; adaptation reduces harm from impacts."},{"prompt":"Which is the best example of adaptation to climate-related flooding?","correct":"Elevating structures and improving drainage in vulnerable areas.","distractors":["Increasing carbon dioxide emissions.","Removing all flood warnings.","Replacing wetlands with pavement."],"explanation":"Adaptation changes infrastructure or behavior to reduce harm from expected conditions."},{"prompt":"Why are wetlands valuable to communities?","correct":"They can store floodwater, filter pollutants, and provide habitat.","distractors":["They always eliminate every flood.","They prevent all evaporation.","They contain no biodiversity."],"explanation":"Wetlands provide multiple ecosystem services, though they cannot remove all risk."},{"prompt":"Which waste-management strategy is highest in the usual reduce–reuse–recycle hierarchy?","correct":"Reduce unnecessary consumption.","distractors":["Recycle after buying more material.","Dispose of reusable items.","Burn all waste without controls."],"explanation":"Preventing waste generally saves more resources and energy than processing discarded material."},{"prompt":"Why should scientific claims in advertising be evaluated critically?","correct":"Claims may omit limitations or use evidence that does not support the conclusion.","distractors":["All advertisements are peer-reviewed research.","A scientific-sounding word guarantees accuracy.","Testimonials are always controlled experiments."],"explanation":"Consumers should examine sources, study design, sample size, and whether conclusions match evidence."}]},"sci-instruction":{"label":"Science Learning, Instruction, and Assessment","description":"Misconceptions, inquiry teaching, formative assessment, differentiation, modeling, questioning, and scientific explanation.","group":"Professional Application","questions":[{"prompt":"Students believe heavier objects always fall faster than lighter objects. Which activity best addresses the misconception?","correct":"Drop objects of similar shape but different mass under the same conditions and compare their motion.","distractors":["Tell students the belief is wrong without evidence.","Compare a flat sheet of paper with a compact metal ball only.","Avoid discussing air resistance."],"explanation":"A controlled comparison isolates mass while minimizing differences in drag."},{"prompt":"Which assessment most directly measures a student’s ability to design an investigation?","correct":"Ask the student to identify variables, controls, measurements, and a procedure for a new question.","distractors":["Ask the student to copy a vocabulary definition.","Grade notebook neatness only.","Count attendance."],"explanation":"Design knowledge is best assessed through an authentic planning task."},{"prompt":"A concept map is especially useful for assessing:","correct":"relationships among scientific ideas.","distractors":["only handwriting speed.","the mass of an object.","laboratory temperature."],"explanation":"Concept maps reveal how learners connect and organize concepts."},{"prompt":"Which question is most likely to promote higher-order scientific thinking?","correct":"What evidence supports your explanation, and what alternative explanation could fit the data?","distractors":["What page is the definition on?","Did you copy the sentence exactly?","Is science interesting—yes or no?"],"explanation":"Evidence evaluation and alternative explanations require analysis rather than recall."},{"prompt":"Before a laboratory investigation, the teacher should first ensure that students:","correct":"understand hazards, safety procedures, and appropriate equipment use.","distractors":["begin mixing materials immediately.","decide safety rules after an accident.","remove protective equipment."],"explanation":"Safety expectations and hazard controls must be established before work begins."},{"prompt":"Which sequence best reflects inquiry-based learning?","correct":"Question → investigation → evidence analysis → explanation → communication","distractors":["Answer → copy → memorize → stop","Equipment → accident → question","Conclusion → alter data → procedure"],"explanation":"Inquiry begins with questions and develops evidence-based explanations that are communicated and evaluated."},{"prompt":"A student’s graph has time on the vertical axis and temperature on the horizontal axis. What feedback is most useful?","correct":"Ask which variable was intentionally changed and which was measured, then revise the axes accordingly.","distractors":["Mark the graph wrong without explanation.","Tell the student every graph must be a bar graph.","Ignore the variable roles."],"explanation":"Feedback should connect graph conventions to independent and dependent variables."},{"prompt":"Which adaptation preserves the cognitive goal of a science task for an English learner?","correct":"Provide labeled visuals and sentence frames while requiring the same evidence-based explanation.","distractors":["Replace the investigation with coloring only.","Remove all scientific vocabulary permanently.","Excuse the student from observing data."],"explanation":"Language supports can improve access without reducing the scientific reasoning required."},{"prompt":"Which classroom practice best distinguishes a model from the actual system?","correct":"Have students state what the model represents accurately and what it omits or distorts.","distractors":["Tell students models are exact copies.","Use only one model and forbid critique.","Avoid comparing the model with evidence."],"explanation":"Evaluating strengths and limitations develops sophisticated understanding of models."},{"prompt":"Formative assessment is used primarily to:","correct":"gather evidence during learning and adjust instruction.","distractors":["assign a final course grade only.","replace all instruction.","rank schools nationally only."],"explanation":"Formative evidence guides immediate teaching and learning decisions."},{"prompt":"Which task best integrates science and mathematics?","correct":"Use repeated measurements to graph a relationship and calculate a rate of change.","distractors":["Memorize unrelated vocabulary lists.","Copy a paragraph with no data.","Avoid numerical evidence."],"explanation":"Analyzing measurements and rates uses mathematics to interpret scientific patterns."},{"prompt":"Students obtain conflicting results in repeated trials. What is the most productive response?","correct":"Examine procedures, measurement uncertainty, and possible uncontrolled variables.","distractors":["Delete all unusual results immediately.","Choose the result closest to the expected answer.","Conclude that evidence is never useful."],"explanation":"Variation should be investigated for error sources and genuine effects rather than hidden."},{"prompt":"Which lesson structure best supports conceptual change?","correct":"Elicit prior ideas, confront them with evidence, and guide students in constructing a better explanation.","distractors":["Present vocabulary without asking what students think.","Reward only memorized statements.","Avoid demonstrations that conflict with misconceptions."],"explanation":"Conceptual change requires making prior models visible and testing them against evidence."},{"prompt":"A rubric for a scientific explanation should give greatest weight to:","correct":"a clear claim supported by relevant evidence and scientific reasoning.","distractors":["decorative borders.","response length regardless of accuracy.","agreement with classmates without evidence."],"explanation":"Strong explanations connect evidence to a defensible claim through scientific principles."},{"prompt":"Which use of technology is most instructionally appropriate?","correct":"Use a simulation to vary one factor and compare predictions with observable evidence, while discussing the simulation’s limits.","distractors":["Use animation as entertainment with no learning goal.","Treat simulated output as infallible.","Replace all hands-on and real-world evidence in every case."],"explanation":"Technology is effective when tied to reasoning goals and evaluated as a model."}]}},"exams":{"ec6-science":{"id":"ec6-science","family":"TExES Core Subjects EC–6","code":"904","title":"Core Subjects EC–6 Science","shortTitle":"EC–6 Science 904","description":"Elementary science knowledge and application across inquiry, physical, life, Earth and space, environment, and instruction.","fullCount":45,"duration":55,"forms":4,"topicVersions":3,"topicCount":10,"categories":["sci-inquiry","sci-physical","sci-chem","sci-life","sci-ecology","sci-earth","sci-space","sci-impact","sci-instruction"],"weights":{"sci-inquiry":7,"sci-physical":7,"sci-chem":5,"sci-life":7,"sci-ecology":4,"sci-earth":5,"sci-space":3,"sci-impact":3,"sci-instruction":4},"note":"The official Science 904 subject exam contains 45 selected-response questions. These forms preserve that length and sample all major framework areas."},"core48-science":{"id":"core48-science","family":"TExES Core Subjects 4–8","code":"809","title":"Core Subjects 4–8 Science","shortTitle":"Core 4–8 Science 809","description":"Middle-level generalist science across inquiry, physical science, life science, Earth and space science, environmental systems, and teaching applications.","fullCount":42,"duration":50,"forms":4,"topicVersions":3,"topicCount":10,"categories":["sci-inquiry","sci-physical","sci-chem","sci-life","sci-ecology","sci-earth","sci-space","sci-impact","sci-instruction"],"weights":{"sci-inquiry":6,"sci-physical":6,"sci-chem":5,"sci-life":6,"sci-ecology":4,"sci-earth":5,"sci-space":3,"sci-impact":3,"sci-instruction":4},"note":"The official Science 809 subject exam contains 42 selected-response questions. The diagnostic reports the broader science areas represented by its competencies."},"science48":{"id":"science48","family":"TExES","code":"116","title":"Science 4–8","shortTitle":"Science 4–8 (116)","description":"Standalone middle-level science preparation aligned to the five official domains and their content competencies.","fullCount":100,"duration":285,"forms":4,"topicVersions":3,"topicCount":12,"categories":["sci-inquiry","sci-physical","sci-chem","sci-life","sci-ecology","sci-earth","sci-space","sci-impact","sci-instruction"],"weights":{"sci-inquiry":18,"sci-physical":12,"sci-chem":10,"sci-life":12,"sci-ecology":10,"sci-earth":13,"sci-space":9,"sci-impact":4,"sci-instruction":12},"note":"The official Science 4–8 (116) exam has 100 selected-response questions. The forms approximate the published domain balance while reporting more specific study areas."}},"labs":[]};const LETTERS=["A","B","C","D"];function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}function rng(seed){let a=hash(seed)||1;return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;}}function shuffle(r,a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}function prep(raw,r,catId,i,seed){const opts=shuffle(r,[{text:raw.correct,ok:true},...raw.distractors.slice(0,3).map(text=>({text,ok:false}))]);return {id:`${catId}-${hash(seed+":"+i+":"+raw.prompt).toString(36)}`,prompt:raw.prompt,stimulus:raw.stimulus||"",choices:opts.map(x=>x.text),answer:opts.findIndex(x=>x.ok),explanation:raw.explanation,categoryId:catId,categoryLabel:DATA.categories[catId].label};}function categoryQuestions(id,count,seed){const c=DATA.categories[id],r=rng(seed),order=shuffle(r,c.questions.map((_,i)=>i)),out=[];for(let i=0;i<count;i++){let raw=c.questions[order[i%order.length]];out.push(prep(raw,r,id,i,seed));}return out;}function full(id,seed){const e=DATA.exams[id],r=rng(seed+":all");let qs=[];e.categories.forEach(c=>qs.push(...categoryQuestions(c,e.weights[c],seed+":"+c)));return shuffle(r,qs);}function topic(examId,catId,seed){const e=DATA.exams[examId];if(!e.categories.includes(catId))throw Error("Topic not in exam");return categoryQuestions(catId,e.topicCount,seed);}global.PracticeData={...DATA,LETTERS,generateFullExam:full,generateTopicQuiz:topic};})(window);